import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../api/client';
import {
  PlayCircle,
  PauseCircle,
  Wrench,
  AlertTriangle,
  Gauge,
  Award,
  Zap,
  TrendingUp,
  Clock,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const SystemStatusBar = () => {
  const navigate = useNavigate();
  const [hoveredKpi, setHoveredKpi] = useState(null);
  const [summaryData, setSummaryData] = useState(null);

  useEffect(() => {
    fetchSummary();
  }, []);

  const fetchSummary = async () => {
    try {
      const res = await dashboardApi.getSummary();
      if (res && res.data && res.data.success) {
        setSummaryData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch summary:', err);
    }
  };

  const kpis = [
    {
      key: 'running',
      title: 'Running Machines',
      value: summaryData ? `${summaryData.running} / ${summaryData.totalAssets || 20}` : '16 / 20',
      status: '90% Operational',
      icon: PlayCircle,
      color: '#16A34A',
      bg: '#DCFCE7',
      borderColor: '#BBF7D0',
      route: '/factory/running-machines',
    },
    {
      key: 'idle',
      title: 'Idle Machines',
      value: summaryData ? `${summaryData.idle || 3}` : '3',
      status: 'Standby',
      icon: PauseCircle,
      color: '#D97706',
      bg: '#FEF3C7',
      borderColor: '#FDE68A',
      route: '/factory/idle-machines',
    },
    {
      key: 'maintenance',
      title: 'Scheduled Maintenance',
      value: '1',
      status: 'Scheduled Service',
      icon: Wrench,
      color: '#EA580C',
      bg: '#FFEDD5',
      borderColor: '#FED7AA',
      route: '/maintenance',
    },
    {
      key: 'alerts',
      title: 'Critical Alerts',
      value: '11',
      status: 'Immediate Action Required',
      icon: AlertTriangle,
      color: '#DC2626',
      bg: '#FEE2E2',
      borderColor: '#FECACA',
      route: '/alerts',
    },
    {
      key: 'production',
      title: "Today's Production",
      value: '14,250 m',
      status: '89% of Daily Target',
      icon: Gauge,
      color: '#2563EB',
      bg: '#DBEAFE',
      borderColor: '#BFDBFE',
      route: '/analytics/production',
    },
    {
      key: 'oee',
      title: 'Overall Equipment Effectiveness',
      value: '96.4%',
      status: 'World Class',
      icon: Award,
      color: '#7C3AED',
      bg: '#F3E8FF',
      borderColor: '#DDD6FE',
      route: '/analytics/oee',
    },
    {
      key: 'energy',
      title: 'Energy Consumption',
      value: '1,245 kWh',
      status: 'Optimal Consumption',
      icon: Zap,
      color: '#059669',
      bg: '#ECFDF5',
      borderColor: '#A7F3D0',
      route: '/analytics/energy',
    },
  ];

  return (
    <section style={{ width: '100%', marginBottom: '1.75rem' }}>
      {/* Full-Width Enterprise Clickable KPI Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))',
          gap: '1.25rem',
          width: '100%',
        }}
      >
        {kpis.map((kpi) => {
          const CardIcon = kpi.icon;
          const isHovered = hoveredKpi === kpi.key;

          return (
            <div
              key={kpi.key}
              onClick={() => navigate(kpi.route)}
              style={{
                background: '#ffffff',
                borderRadius: '8px',
                padding: '1.25rem 1.35rem',
                border: isHovered ? `2px solid ${kpi.color}` : `1px solid ${kpi.borderColor}`,
                boxShadow: isHovered
                  ? `0 8px 20px ${kpi.color}20`
                  : '0 2px 10px rgba(0, 0, 0, 0.04)',
                transform: isHovered ? 'translateY(-3px)' : 'none',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                transition: 'all 0.2s ease',
                minHeight: '140px',
                cursor: 'pointer',
                position: 'relative',
              }}
              onMouseEnter={() => setHoveredKpi(kpi.key)}
              onMouseLeave={() => setHoveredKpi(null)}
            >
              {/* Header: Icon & Title */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.5rem' }}>
                <span style={{ fontSize: '0.88rem', fontWeight: '800', color: '#334155', lineHeight: '1.3' }}>
                  {kpi.title}
                </span>

                <div
                  style={{
                    width: '36px',
                    height: '36px',
                    borderRadius: '8px',
                    background: kpi.bg,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: kpi.color,
                    flexShrink: 0,
                  }}
                >
                  <CardIcon size={19} />
                </div>
              </div>

              {/* Body: Value & Status Line */}
              <div style={{ marginTop: '0.75rem' }}>
                <div
                  style={{
                    fontSize: '1.9rem',
                    fontWeight: '900',
                    color: '#0F172A',
                    lineHeight: '1.1',
                    letterSpacing: '-0.5px',
                    fontFamily: 'Plus Jakarta Sans, sans-serif',
                  }}
                >
                  {kpi.value}
                </div>

                <div
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: '700',
                    color: kpi.color,
                    marginTop: '0.4rem',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                  }}
                >
                  <TrendingUp size={13} /> {kpi.status}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default SystemStatusBar;
